$check((int)$pdo->query("SELECT COUNT(*) FROM survey_responses WHERE identity_mode='anonymous' AND (user_id IS NOT NULL OR display_name<>'')")->fetchColumn()===0,'Signed-in anonymity omits account reference.');
$session->forget('survey.key.'.$slug);
$check($controller->feedback(new Request(body:$named,server:$json))->status()===200,'Signed-in identified response accepted.');
